/**
 * Shake: jitters the object back and forth around its position.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { Ticker } from "pixi.js";
import { Component, isEditorPaused } from "../core";

export interface ShakeParams {
  /** Maximum offset from the base position, in pixels. */
  amount: number;
  /** Shakes per second. */
  speed: number;
}

/** Jitters the object around its position. Paused in Edit mode — switch to Play to preview. */
export class Shake extends Component<ShakeParams> {
  static readonly componentName = "Shake";
  static readonly defaults: ShakeParams = { amount: 4, speed: 8 };

  private time = 0;
  private applied = { x: 0, y: 0 };
  private written = { x: NaN, y: NaN };

  update(): void {
    this.reset();
    if (isEditorPaused()) return;
    this.time += Ticker.shared.deltaMS / 1000;
    const phase = this.time * this.params.speed * Math.PI * 2;
    this.applied = {
      x: Math.sin(phase) * this.params.amount,
      y: Math.cos(phase * 1.3) * this.params.amount,
    };
    const t = this.target;
    t.x += this.applied.x;
    t.y += this.applied.y;
    this.written = { x: t.x, y: t.y };
  }

  detach(): void {
    this.reset();
  }

  /** Removes last frame's shake offset, unless something else moved the object since. */
  private reset(): void {
    const t = this.target;
    if (this.applied.x !== 0 && t.x === this.written.x) t.x -= this.applied.x;
    if (this.applied.y !== 0 && t.y === this.written.y) t.y -= this.applied.y;
    this.applied = { x: 0, y: 0 };
  }
}
